def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'D'
    if n == 3:
        return 'C'
    if n == 99:
        return 'D'
    for i in range(n):
        if history[i][1] == 'D':
            return 'C'
    if n % 2 == 0:
        return 'D'
    return 'C'
